/*!40000 ALTER TABLE `recipes` DISABLE KEYS */;
INSERT INTO `recipes` VALUES (1,4,'Класична Паска','Ароматна здобна паска з родзинками та цукатами.','img/paska_classic.jpg',15,'1. Збір доказів. Приготуйте опару з дріжджів, теплого молока та частини борошна.\n2. Допит свідків. Додайте збиті яйця, жовтки, цукор та розтоплене масло.\n3. Секретна інтеграція. Вмішайте родзинки та вимісіть тісто.\n4. Гарячий слід. Випікайте при 180°C до сухої палички.'),(2,4,'Сирна Паска (без випічки)','Ніжний сирний десерт з вершками та горіхами.','img/paska_curd.jpg',12,'1. Аналіз матеріалів. Перетріть кисломолочний сир через дрібне сито двічі.\n2. Допит з пристрастю. Збийте жирні вершки з пудрою до щільності.\n3. Маскування. Додайте розм\'якшене масло, цукати та горіхи, обережно перемішайте.\n4. Ізолятор. Покладіть масу у пасочницю під гніт у холодильник на ніч.'),(3,4,'Шоколадна Паска','Сучасна версія традиційної паски з насиченим смаком шоколаду.','img/paska_choc.jpg',14,'1. Пошук зачіпок. Розчиніть какао в теплому молоці та додайте в основне здобне тісто.\n2. Секретна інтеграція. Перед вистоюванням вмішайте всередину шоколадні краплі.\n3. Гарячий слід. Випікайте до готовності.\n4. Справа закрита. Повністю охолодіть і полийте розтопленою шоколадною глазур\'ю.'),(4,4,'Панеттоне','Італійська святкова випічка з великою кількістю цукатів.','img/panettone.jpg',16,'1. Засідка. Зробіть опару і залиште для тривалого бродіння (мінімум 12 годин).\n2. Слідчий експеримент. Додайте велику кількість вершкового масла та жовтків, вимішуйте до \"глютенового вікна\".\n3. Вербування. Вмішайте цукати.\n4. Особливий режим. Після випікання обов\'язково охолоджуйте догори ногами на шпажках.'),(5,4,'Великодні Зайчики','Медове печиво у формі зайчиків для дітей.','img/bunnies.jpg',10,'1. Підготовка бази. Нагрійте мед з маслом та спеціями.\n2. Формування справи. Замісіть еластичне медове тісто з содою та борошном.\n3. Складання фоторобота. Розкачайте тісто та виріжте фігурки зайчиків.\n4. Гарячий слід. Випікайте 8-10 хвилин і розпишіть білковою глазур\'ю.'),(6,4,'Лимонний Великодній Кекс','Легкий кекс з цедрою та лимонним курдом.','img/lemon_cake.jpg',20,'1. Допит головних підозрюваних. Збийте м\'яке масло з цукром та натертою цедрою до побіління.\n2. Перехресний допит. По одному введіть яйця та лимонний сік.\n3. Замітання слідів. Вмішайте борошно з розпушувачем.\n4. Гарячий слід. Випікайте 45 хвилин при 170°C..'),(7,4,'Сирник \"Сльози Ангела\"','Класичний сирник з ніжною меренгою зверху.','img/angel_tears.jpg',22,'1. Фундамент розслідування. Замісіть пісочне тісто та викладіть його як основу.\n2. Збір доказів. Збийте сирну масу з жовтками та сметаною, вилийте на основу і запікайте.\n3. Секретна операція. За 10-15 хвилин до кінця випікання викладіть зверху збиті з пудрою білки.\n4. Спецефект. Охолоджуйте в духовці, щоб з\'явилися \"сльозинки\" (крапельки карамелі).'),(8,4,'Маковий рулет святковий','Традиційний рулет з великою кількістю макової начинки.','img/poppy_roll.jpg',25,'1. Експертиза. Запарьте мак окропом, злийте воду та перетріть його з цукром і білком.\n2. Огляд місця події. Розкачайте тонкий пласт дріжджового тіста.\n3. Маскування. Викладіть макову начинку, відступаючи від країв, і щільно скрутіть рулет.\n4. Гарячий слід. Випікайте при 180°C близько 35-40 хвилин.'),(9,4,'Морквяний торт з горіхами','Пряний десерт, який ідеально підходить до весняного свята.','img/carrot_cake.jpg',20,'1. Підготовка речових доказів. Натріть моркву на дуже дрібній тертці.\n2. Слідчий експеримент. Змішайте збиті з цукром яйця, олію, борошно, горіхи та корицю.\n3. Гарячий слід. Випікайте коржі при 180°C.\n4. Зшивання справи. Перемажте охолоджені коржі кремом із збитого маскарпоне з пудрою.'),(10,4,'Шоколадні \"Гнізда\"','Десерт без випічки з пластівців та шоколаду.','img/nests.jpg',8,'1. Розтоплення льоду. Розтопіть темний шоколад на водяній бані разом з маслом.\n2. Секретна інтеграція. Обережно вмішайте кукурудзяні пластівці, щоб вони повністю покрилися шоколадом.\n3. Групування свідків. Сформуйте невеликі гнізда на пергаменті.\n4. Справа закрита. Охолодіть і покладіть всередину шоколадні яйця або драже.'),(11,1,'Тірамісу Класичне','Легендарний італійський десерт на основі кави.','img/tiramisu.jpg',20,'1. Нічний патруль. Заваріть міцний еспресо та дайте йому охолонути.\n2. Допит з пристрастю. Збийте маскарпоне з жовтками та цукром до густого крему.\n3. Слідчий експеримент. Швидко занурюйте печиво савоярді в каву та викладайте у форму шарами, чергуючи з кремом.\n4. Фінальний акорд. Перед подачею посипте какао-порошком.'),(12,1,'Наполеон домашній','Багатошаровий торт з ніжним заварним кремом.','img/napoleon.jpg',24,'1. Збір доказів. Посічіть холодне масло з борошном, додайте крижану воду і замісіть тісто. Охолодіть.\n2. Гарячий слід. Розкачайте і випечіть 10-12 дуже тонких коржів при 200°C.\n3. Хімічний аналіз. Зваріть заварний крем на молоці та жовтках.\n4. Зшивання справи. Перемажте коржі гарячим кремом і залиште торт настоюватися мінімум 12 годин.'),(13,1,'Медовик зі сметаною','Ароматні медові коржі та кислинка сметанного крему.','img/medovik.jpg',22,'1. Хімічна реакція. Розтопіть мед, масло і цукор на водяній бані. Додайте соду (маса має спінитися).\n2. Формування справи. Вмішайте яйця і борошно, замісіть тісто.\n3. Гарячий слід. Розкачайте тонкі коржі і випікайте по 3-4 хвилини.\n4. Зшивання справи. Перемажте коржі кремом із жирної сметани, збитої з пудрою.'),(14,1,'Празький торт','Шоколадний торт з насиченим масляним кремом.','img/prague.jpg',20,'1. Підготовка бази. Збийте яйця з цукром, обережно вмішайте борошно, какао та розтоплене масло. Випечіть бісквіт.\n2. Аналіз матеріалів. Для крему заваріть жовток з водою і згущеним молоком, охолодіть і збийте з маслом та какао.\n3. Секретна операція. Розріжте бісквіт, промажте кремом.\n4. Маскування. Обмажте торт абрикосовим джемом і залийте шоколадною глазур\'ю.'),(15,1,'Чізкейк Нью-Йорк','Класичний запечений чізкейк з вершкового сиру.','img/ny_cheesecake.jpg',22,'1. Фундамент розслідування. Подрібніть пісочне печиво в крихту, змішайте з розтопленим маслом і утрамбуйте на дно форми.\n2. Збір доказів. Крем-сир перемішайте (не збивайте!) з цукром, яйцями та вершками.\n3. Секретна інтеграція. Вилийте начинку на основу.\n4. Водяна баня. Випікайте на водяній бані при 130°C близько 1.5 години. Охолоджуйте в духовці.'),(16,1,'Червоний оксамит','Яскраво-червоні коржі з легким присмаком какао.','img/red_velvet.jpg',18,'1. Маскування. Змішайте кефір, олію, яйця та харчовий червоний барвник.\n2. Аналіз матеріалів. Додайте сухі інгредієнти: борошно, трохи какао, цукор і соду.\n3. Гарячий слід. Випечіть коржі при 170°C.\n4. Зшивання справи. Перемажте торт стабільним кремом на основі крем-сиру та вершкового масла.'),(17,1,'Три шоколади','Мусовий торт з трьох видів шоколаду.','img/three_choc.jpg',18,'1. Основа справи. Спечіть тонкий шоколадний бісквіт для основи.\n2. Хімічний аналіз. Зробіть заварну базу на жовтках, розділіть на три частини і додайте в кожну різний шоколад та желатин.\n3. Секретна інтеграція. Вмішайте збиті вершки в кожен мус.\n4. Ізолятор. Заливайте муси у кільце почергово, чекаючи застигання кожного шару в морозилці.'),(18,1,'Естерхазі','Мигдально-фундучний торт без борошна.','img/esterhazy.jpg',20,'1. Допит свідків. Збийте білки з цукром до міцних піків, обережно вмішайте мелені горіхи.\n2. Складання фоторобота. Намалюйте кола на пергаменті та випечіть 5-6 горіхових коржів.\n3. Аналіз матеріалів. Зваріть заварний крем і збийте його з вершковим маслом.\n4. Фірмовий почерк. Перемажте коржі, а зверху намалюйте фірмову шоколадну павутинку.'),(19,1,'Торт \"Захер\"','Австрійський шоколадний торт з абрикосовим конфітюром.','img/sacher.jpg',20,'1. Перехресний допит. Збийте масло з шоколадом, введіть жовтки. Окремо збийте білки з цукром.\n2. Об\'єднання справ. З\'єднайте маси з борошном і випечіть щільний шоколадний бісквіт.\n3. Секретна операція. Розріжте бісквіт і рясно змажте підігрітим абрикосовим джемом (всередині і зовні).\n4. Маскування. Покрийте торт глазур\'ю з чорного шоколаду та вершків.'),(20,1,'Меренговий рулет з ягодами','Повітряний десерт, що тане у роті.','img/meringue_roll.jpg',25,'1. Допит з пристрастю. Збийте білки з пудрою до стійких піків, додайте лимонний сік та крохмаль.\n2. Гарячий слід. Розподіліть масу по пергаменту і випікайте при 150°C близько 20-25 хвилин до скоринки.\n3. Зворотний бік медалі. Переверніть і охолодіть.\n4. Замітання слідів. Змажте кремом (маскарпоне + вершки), викладіть ягоди і обережно згорніть у рулет.'),(21,1,'Пташине молоко','Ніжне суфле на агар-агарі в шоколаді.','img/bird_milk.jpg',20,'1. Основа справи. Випечіть тонкий і щільний бісквіт для основи.\n2. Хімічна реакція. Зваріть сироп з водою, цукром та агар-агаром до 110°C.\n3. Об\'єднання матеріалів. Збийте білки і тонкою цівкою влийте гарячий сироп. Вмішайте збите масло зі згущеним молоком.\n4. Справа закрита. Вилийте суфле на бісквіт, охолодіть і залийте шоколадною глазур\'ю.'),(22,1,'Торт \"Павлова\"','Легка меренга з хрусткою скоринкою та м\'якою серединою.','img/pavlova.jpg',15,'1. Допит свідків. Збийте білки з цукром до глянцю, додайте оцет та кукурудзяний крохмаль.\n2. Огляд місця події. Сформуйте на пергаменті гніздо з високими бортами.\n3. Тривала засідка. Сушіть у духовці при 100°C близько 1.5-2 годин.\n4. Фінальний акорд. Перед самою подачею наповніть збитими вершками без цукру та великою кількістю ягід.'),(23,1,'Шварцвальдський торт','Шоколадний торт з вишнею та збитими вершками.','img/black_forest.jpg',22,'1. Підготовка доказів. Спечіть класичний шоколадний бісквіт і розріжте на 3 коржі.\n2. Секретний інгредієнт. Проваріть вишню з цукром і крохмалем для начинки. Просочіть коржі вишневим сиропом.\n3. Допит з пристрастю. Збийте жирні вершки з пудрою.\n4. Зшивання справи. Зберіть торт: корж, вершки, вишня. Зверху прикрасьте шоколадною стружкою.'),(24,1,'Торт \"Рафаелло\"','Ніжний кокосовий торт з мигдалем.','img/raffaello_cake.jpg',18,'1. Гарячий слід. Випечіть пишний бісквіт з додаванням мигдального борошна.\n2. Аналіз матеріалів. Для крему розтопіть білий шоколад у вершках, охолодіть і збийте з маскарпоне.\n3. Секретна інтеграція. Додайте в крем кокосову стружку та подрібнений бланшований мигдаль.\n4. Маскування. Перемажте коржі та обсипте весь торт кокосом.'),(25,1,'Торт \"Опера\"','Класика французького кондитерського мистецтва.','img/opera.jpg',15,'1. Підготовка бази. Випечіть дуже тонкі мигдальні бісквіти \"Джоконда\".\n2. Хімічний аналіз. Приготуйте масляно-кавовий крем на жовтках та шоколадний ганаш.\n3. Секретна операція. Рясно просочіть кожен корж кавовим сиропом.\n4. Зшивання справи. Зберіть торт, чергуючи дуже тонкі шари бісквіта, кавового крему та ганаша.'),(26,2,'ПП Брауні','Шоколадний десерт на основі банана та какао без цукру.','img/pp_brownie.jpg',15,'1. Підготовка доказів. Розімніть стиглі банани виделкою в пюре.\n2. Слідчий експеримент. Додайте яйця, какао, розпушувач та трохи олії. Перемішайте до однорідності.\n3. Фіксація доказів. Вилийте у невелику форму.\n4. Гарячий слід. Випікайте при 180°C близько 20 хвилин. Десерт має залишитися злегка вологим всередині.'),(27,2,'Чіа-пудинг з манго','Корисний сніданок або легкий десерт.','img/chia.jpg',10,'1. Збір доказів. Залийте насіння чіа молоком, додайте краплю меду, добре перемішайте.\n2. Ізолятор. Залиште в холодильнику на 2-3 години або на ніч, щоб насіння набрякло.\n3. Хімічний аналіз. Зробіть пюре зі свіжого манго у блендері.\n4. Зшивання справи. Викладіть у склянку шарами: чіа-пудинг і мангове пюре.'),(28,2,'Вівсяне печиво з яблуком','Без борошна та цукру, лише користь.','img/oat_cookie.jpg',10,'1. Пошук зачіпок. Натріть солодке яблуко на тертці.\n2. Секретна інтеграція. Змішайте яблуко з вівсяними пластівцями, яйцем та подрібненими горіхами.\n3. Засідка. Дайте масі постояти 15 хвилин, щоб пластівці розм\'якшилися.\n4. Гарячий слід. Сформуйте печиво і випікайте 15 хвилин при 180°C.'),(29,2,'Кокосові цукерки','Домашні цукерки на кшталт \"Баунті\" без цукру.','img/coco_candies.jpg',5,'1. Слідчий експеримент. Змішайте кокосову стружку з густими вершками та краплею меду до липкої маси.\n2. Ізолятор. Сформуйте невеликі батончики і покладіть у морозилку на 30 хвилин.\n3. Підготовка маскування. Розтопіть чорний шоколад (від 75%).\n4. Операція під прикриттям. Занурте кожен батончик у шоколад і викладіть на пергамент застигати.'),(30,2,'Сирна запіканка з курагою','Класична запіканка на стевії.','img/curd_pp.jpg',20,'1. Допит з пристрастю. Перебийте сир блендером разом з яйцями, сметаною та стевією до кремового стану.\n2. Секретна інтеграція. Додайте кукурудзяний крохмаль і добре перемішайте.\n3. Вербування. Наріжте курагу дрібними кубиками і вмішайте в масу.\n4. Гарячий слід. Випікайте у силіконовій формі 40 хвилин при 170°C.'),(31,2,'Банановий хліб з горіхами','Ароматний кекс без доданого цукру.','img/banana_bread.jpg',18,'1. Підготовка речових доказів. Розімніть дуже стиглі (з чорними крапками) банани в пюре.\n2. Слідчий експеримент. Змішайте з яйцями, олією та борошном із розпушувачем.\n3. Секретна інтеграція. Додайте січені волоські горіхи.\n4. Гарячий слід. Випікайте у формі для кексу при 180°C близько 45-50 хвилин.'),(32,2,'Морквяні мафіни ПП','Здорові мафіни з горіхами та родзинками.','img/carrot_muffin.jpg',8,'1. Пошук зачіпок. Натріть моркву на дрібній тертці.\n2. Слідчий експеримент. Змішайте вівсяне борошно, моркву, яйця, кефір, розпушувач та мед.\n3. Вербування. Вмішайте попередньо замочені родзинки.\n4. Гарячий слід. Розкладіть по формочках для мафінів і випікайте 25 хвилин.'),(33,2,'Ягідний сорбет','Заморожений десерт з чистих ягід.','img/sorbet.jpg',10,'1. Заморожені свідки. Візьміть сильно заморожені ягоди (полуниця, малина).\n2. Допит. Покладіть їх у потужний блендер, додайте трохи теплої води, лимонний сік та мед.\n3. Допит з пристрастю. Збийте до однорідної густої маси.\n4. Справа закрита. Подавайте одразу або поставте в морозилку на 30 хвилин для більшої щільності.'),(34,2,'Авокадо-шоколадний мус','Кремовий десерт зі здоровими жирами.','img/avocado_mousse.jpg',10,'1. Експертиза. Почистіть стигле м\'яке авокадо і видаліть кісточку.\n2. Збір доказів. Покладіть у блендер авокадо, какао-порошок, молоко та мед.\n3. Перехресний допит. Перебийте масу до ідеально гладкого, шовковистого кремового стану.\n4. Ізолятор. Розкладіть по креманках і охолодіть перед подачею.'),(35,2,'Яблука запечені з медом','Найпростіший та найкорисніший десерт.','img/baked_apples.jpg',12,'1. Огляд місця події. Помийте яблука і обережно виріжте серцевину, не прорізаючи яблуко наскрізь.\n2. Секретна інтеграція. Змішайте подрібнені горіхи з родзинками.\n3. Маскування. Наповніть серединку яблук цією сумішшю і полийте медом.\n4. Гарячий слід. Запікайте 20-25 хвилин при 180°C до м\'якості яблук.'),(36,3,'Макаруни асорті','Французьке печиво на мигдальному борошні.','img/macarons.jpg',5,'1. Збір доказів. Змішайте мигдальне борошно з пудрою і просійте.\n2. Допит з пристрастю. Збийте білки з цукром у меренгу, обережно вмішайте суху суміш (зробіть макаронаж).\n3. Засідка. Відсадіть кружальця на килимок і дайте їм підсохнути 30 хвилин до утворення плівки.\n4. Справа закрита. Випікайте при 140°C, після охолодження з\'єднайте половинки ганашем.'),(37,5,'Еклери ванільні','Заварне тісто з ніжним кремом.','img/eclairs.jpg',12,'1. Хімічна реакція. Доведіть воду з молоком і маслом до кипіння, всипте борошно і заваріть тісто.\n2. Перехресний допит. Поступово вмішайте яйця до отримання правильної консистенції.\n3. Гарячий слід. Відсадіть смужки тіста і випікайте без відкривання дверцят духовки.\n4. Маскування. Наповніть охолоджені еклери заварним кремом і покрийте помадкою.'),(38,3,'Кантучіні','Сухе італійське печиво з цілим мигдалем.','img/cantuccini.jpg',8,'1. Збір доказів. Змішайте борошно, цукор, розпушувач, яйця та цедру.\n2. Секретна інтеграція. Вмішайте в тісто цілий сирий мигдаль. Сформуйте довгі батони.\n3. Гарячий слід. Випечіть батони до золотистого кольору (близько 25 хвилин).\n4. Фінальний допит. Дістаньте, наріжте по діагоналі на скибки і підсушіть їх у духовці ще 10 хвилин.'),(39,5,'Профітролі з шоколадом','Маленькі кульки з кремовою начинкою.','img/profiteroles.jpg',4,'1. Підготовка бази. Приготуйте класичне заварне тісто (як для еклерів).\n2. Фіксація доказів. Відсадіть на деко маленькі кульки розміром з волоський горіх.\n3. Гарячий слід. Випікайте до золотистої скоринки і повного висихання всередині.\n4. Секретна операція. Начиніть збитими вершками і рясно полийте шоколадним соусом.'),(40,3,'Горішки зі згущеним молоком','Смак дитинства.','img/nuts_cookie.jpg',4,'1. Перехресний допит. Розітріть м\'яке масло з цукром та жовтками. Додайте борошно і гашену соду.\n2. Формування справи. Замісіть м\'яке пісочне тісто.\n3. Гарячий слід. Відщипуйте маленькі шматочки тіста і випікайте у спеціальній формі-горішниці.\n4. Зшивання справи. Наповніть охолоджені половинки вареним згущеним молоком і з\'єднайте.'),(41,5,'Капкейки \"Орео\"','Шоколадні мафіни з кремом на основі печива.','img/oreo_cupcakes.jpg',7,'1. Збір доказів. Змішайте сухі інгредієнти (какао, борошно, цукор) з вологими (яйця, молоко, масло).\n2. Секретна інтеграція. Додайте в тісто поламані шматочки печива Орео і випікайте у формочках.\n3. Допит з пристрастю. Збийте крем-сир з маслом та пудрою, додайте дрібну крихту печива.\n4. Маскування. Відсадіть крем шапочкою на охолоджені капкейки.'),(42,5,'Фруктовий тарт','Пісочна основа з заварним кремом та свіжими фруктами.','img/fruit_tart.jpg',22,'1. Фундамент розслідування. Замісіть рублене пісочне тісто, розподіліть по формі для тарта і випечіть з вантажем.\n2. Хімічний аналіз. Зваріть класичний крем патісьєр (заварний на жовтках з молоком).\n3. Об\'єднання матеріалів. Викладіть холодний крем у випечену і охолоджену основу.\n4. Фінальний акорд. Прикрасьте зверху великою кількістю свіжих ягід та фруктів.'),(43,3,'Шоколадне печиво з тріщинками','Красиве та дуже смачне печиво.','img/cracked_cookies.jpg',8,'1. Розтоплення льоду. Розтопіть шоколад з маслом. Збийте яйця з цукром.\n2. Об\'єднання справ. З\'єднайте маси, додайте борошно з какао і розпушувачем. Охолодіть тісто в холодильнику.\n3. Маскування. Скатайте кульки і дуже щедро обваляйте їх у цукровій пудрі.\n4. Гарячий слід. Випікайте 10-12 хвилин при 180°C. Печиво розтріскається і стане красивим.'),(44,5,'Трюфелі ручної роботи','Цукерки з якісного шоколаду та вершків.','img/truffles.jpg',3,'1. Слідчий експеримент. Нагрійте жирні вершки майже до кипіння.\n2. Хімічна реакція. Вилийте гарячі вершки на подрібнений чорний шоколад. Додайте шматочок масла і перемішайте.\n3. Ізолятор. Накрийте ганаш плівкою в контакт і охолодіть мінімум 4 години.\n4. Маскування. Скатайте кульки і обваляйте їх у гіркому какао-порошку.'),(45,5,'Зефір яблучний','Натуральний домашній зефір на агарі.','img/zefir.jpg',6,'1. Експертиза. Запечіть яблука і перетріть у густе пюре. Збийте пюре з білком до пишності.\n2. Хімічний аналіз. Зваріть сироп з цукру, води та агар-агару до 110°C.\n3. Допит з пристрастю. Не припиняючи збивати, влийте гарячий сироп у білково-яблучну масу.\n4. Закриття справи. Швидко відсадіть половинки зефіру і залиште стабілізуватися на 12-24 години.'),(46,5,'Панна котта з полуницею','Вершкове желе з ягідним соусом.','img/panna_cotta.jpg',10,'1. Збір доказів. Замочіть желатин у холодній воді.\n2. Хімічна реакція. Нагрійте вершки з молоком та цукром (не кип\'ятіть!). Введіть набряклий желатин.\n3. Ізолятор. Розлийте масу по формах або келихах і поставте в холодильник до застигання.\n4. Фінальний штрих. Зверху викладіть пюре зі свіжої полуниці з пудрою.'),(47,3,'Віденське печиво','Тертий пиріг у форматі печива з варенням.','img/vienna_cookies.jpg',10,'1. Перехресний допит. Розітріть масло з цукром та борошном до стану крихти (або замісіть тісто і заморозьте частину).\n2. Фіксація доказів. Викладіть більшу частину тіста на деко і злегка притисніть.\n3. Секретна операція. Намажте шаром густого кислого варення (смородина або слива).\n4. Гарячий слід. Зверху засипте залишками крихти і випікайте до золотистого кольору. Наріжте гарячим.'),(48,5,'Трубочки з білковим кремом','Хрустке тісто та невагомий крем.','img/cream_rolls.jpg',15,'1. Експертиза. Наріжте готове листкове тісто довгими смужками.\n2. Гарячий слід. Накрутіть смужки на спеціальні металеві конуси внапух і випечіть до золотистості.\n3. Хімічний аналіз. Зваріть цукровий сироп і влийте його у збиті білки (італійська меренга).\n4. Зшивання справи. Начиніть охолоджені трубочки кремом за допомогою кондитерського мішка.'),(49,1,'Вафельний торт','Класика з вареною згущенкою та горіхами.','img/waffle_cake.jpg',24,'1. Допит свідків. Збийте м\'яке вершкове масло міксером до побіління.\n2. Перехресний допит. Поступово додавайте варене згущене молоко, продовжуючи збивати крем.\n3. Зшивання справи. Перемажте готові хрусткі вафельні коржі цим кремом.\n4. Фінальний акорд. Кожен шар (або через один) посипайте подрібненими горіхами. Дайте настоятись.'),(50,5,'Штрудель яблучний','Тонке витяжне тісто з яблуками та корицею.','img/strudel.jpg',30,'1. Формування справи. Замісіть еластичне тісто з борошна, води і олії. Дайте йому відпочити.\n2. Збір доказів. Наріжте яблука, змішайте з цукром, корицею та родзинками.\n3. Секретна операція. Розтягніть тісто на рушнику до стану паперу, змажте маслом і викладіть начинку.\n4. Гарячий слід. Згорніть за допомогою рушника у рулет і запікайте до хрусткої скоринки.'),(52,1,'Бісквіт Джоконда','Базовий бісквіт для торта \"Опера\"','img/dzhokonda.jpg',20,'1. Збийте яєчні білки з дрібним цукром до стійких піків (меренга). \n2. В окремій мисці збийте мигдалеве борошно, цукрову пудру та цілі яйця до світлої і пухкої маси (близько 5-10 хв). \n3. Акуратно введіть просіяне пшеничне борошно. \n4. Обережно підмішайте збиті білки в мигдалеве тісто за допомогою силіконової лопатки (рухами знизу вгору). \n5. В самому кінці влийте розтоплене (але не гаряче) вершкове масло і ще раз обережно перемішайте. \n6. Вилийте тісто на деко, застелене пергаментом, розрівняйте тонким шаром (близько 5 мм). \n7. Випікайте при 200°C близько 10-12 хвилин до золотистого кольору.');
